--
-- Table structure for table `expense_records`
--

DROP TABLE IF EXISTS `expense_records`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `expense_records` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `expense_category_id` bigint(20) unsigned NOT NULL,
  `expense_template_id` bigint(20) unsigned DEFAULT NULL,
  `source_performance_record_id` bigint(20) unsigned DEFAULT NULL,
  `source` enum('manual','automatic') NOT NULL DEFAULT 'manual',
  `generation_key` varchar(255) DEFAULT NULL,
  `expense_date` date NOT NULL,
  `competence_start_date` date DEFAULT NULL,
  `competence_end_date` date DEFAULT NULL,
  `competence_months_count` smallint(5) unsigned NOT NULL DEFAULT 1,
  `competence_month` tinyint(3) unsigned NOT NULL,
  `competence_year` smallint(5) unsigned NOT NULL,
  `description` varchar(255) NOT NULL,
  `type` enum('fixed','variable') NOT NULL,
  `amount` decimal(12,2) NOT NULL,
  `supplier` varchar(255) DEFAULT NULL,
  `payment_status` enum('da_pagare','pagata') NOT NULL DEFAULT 'pagata',
  `notes` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `expense_records_generation_key_unique` (`generation_key`),
  UNIQUE KEY `expense_records_source_performance_generation_unique` (`source_performance_record_id`,`generation_key`),
  KEY `expense_records_expense_category_id_foreign` (`expense_category_id`),
  KEY `expense_records_expense_template_id_foreign` (`expense_template_id`),
  KEY `expense_records_expense_date_index` (`expense_date`),
  KEY `expense_records_competence_month_index` (`competence_month`),
  KEY `expense_records_competence_year_index` (`competence_year`),
  KEY `expense_records_type_index` (`type`),
  KEY `expense_records_payment_status_index` (`payment_status`),
  KEY `expense_records_source_index` (`source`),
  KEY `expense_records_competence_start_date_index` (`competence_start_date`),
  KEY `expense_records_competence_end_date_index` (`competence_end_date`),
  KEY `expense_records_source_performance_record_id_index` (`source_performance_record_id`),
  CONSTRAINT `expense_records_expense_category_id_foreign` FOREIGN KEY (`expense_category_id`) REFERENCES `expense_categories` (`id`),
  CONSTRAINT `expense_records_expense_template_id_foreign` FOREIGN KEY (`expense_template_id`) REFERENCES `expense_templates` (`id`) ON DELETE SET NULL,
  CONSTRAINT `expense_records_source_performance_record_id_foreign` FOREIGN KEY (`source_performance_record_id`) REFERENCES `performance_records` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2215 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `expense_records`
--

LOCK TABLES `expense_records` WRITE;
