DROP TABLE IF EXISTS `expense_templates`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `expense_templates` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `category_id` bigint(20) unsigned NOT NULL,
  `name` varchar(255) NOT NULL,
  `type` enum('fixed','variable') NOT NULL,
  `recurrence` enum('weekly','monthly','bimonthly','quarterly','yearly','manual') NOT NULL DEFAULT 'monthly',
  `default_amount` decimal(12,2) NOT NULL,
  `start_date` date DEFAULT NULL,
  `end_date` date DEFAULT NULL,
  `day_of_generation` tinyint(3) unsigned DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `notes` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `expense_templates_category_id_foreign` (`category_id`),
  KEY `expense_templates_type_index` (`type`),
  KEY `expense_templates_recurrence_index` (`recurrence`),
  KEY `expense_templates_is_active_index` (`is_active`),
  CONSTRAINT `expense_templates_category_id_foreign` FOREIGN KEY (`category_id`) REFERENCES `expense_categories` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
