INSERT INTO `pages` VALUES (1,NULL,'chi-siamo','Chi siamo','chi-siamo','default','Remedic e il centro medico polispecialistico di Acireale nato per offrire visite, diagnostica e percorsi di prevenzione con un approccio rapido, accessibile e umano.','Un centro polispecialistico ad Acireale nato per offrire visite, diagnostica e percorsi di prevenzione con un approccio rapido, accessibile e umano.',NULL,NULL,'Chi siamo | Remedic','Scopri l’identita di Remedic, il centro medico polispecialistico di Acireale che coordina visite, diagnostica e prevenzione.','Remedic, il centro medico pensato su di te',NULL,'index,follow',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,1,'2026-06-14 11:01:13','2026-06-14 11:01:13','2026-06-14 11:01:13'),(2,NULL,'privacy','Privacy Policy','privacy','legal','Informazioni sul trattamento dei dati personali raccolti tramite il sito e i canali di contatto Remedic.','Una versione leggibile e ordinata della policy, progettata per essere completata con i riferimenti legali definitivi.',NULL,NULL,'Privacy Policy | Remedic','Informazioni sul trattamento dei dati personali relativi ai servizi e ai contatti del sito Remedic.','Privacy Policy',NULL,'index,follow',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,1,'2026-06-14 11:01:13','2026-06-14 11:01:13','2026-06-14 11:01:13'),(3,NULL,'cookie-policy','Cookie Policy','cookie-policy','legal','Informazioni sull’utilizzo dei cookie e sulle preferenze di consenso del sito Remedic.','Una pagina legale piu leggibile, coerente con il sito e pronta per accogliere il testo definitivo.',NULL,NULL,'Cookie Policy | Remedic','Informazioni sull’utilizzo dei cookie, degli strumenti di tracciamento e sulle preferenze di consenso del sito Remedic.','Cookie Policy',NULL,'index,follow',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,1,'2026-06-14 11:01:13','2026-06-14 11:01:13','2026-06-14 11:01:13'),(4,NULL,'medicina-di-genere','Medicina di genere','medicina-di-genere','default','Percorsi di prevenzione e cura pensati per