  `performance_record_id` bigint(20) unsigned NOT NULL,
  `subject_type` enum('professional','center') NOT NULL,
  `professional_id` bigint(20) unsigned DEFAULT NULL,
  `professional_name_snapshot` varchar(255) DEFAULT NULL,
  `amount` decimal(12,2) NOT NULL,
  `description` varchar(255) DEFAULT NULL,
  `sort_order` int(10) unsigned NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `performance_record_splits_professional_id_foreign` (`professional_id`),
  KEY `performance_record_splits_performance_record_id_sort_order_index` (`performance_record_id`,`sort_order`),
  KEY `performance_record_splits_subject_type_index` (`subject_type`),
  CONSTRAINT `performance_record_splits_performance_record_id_foreign` FOREIGN KEY (`performance_record_id`) REFERENCES `performance_records` (`id`) ON DELETE CASCADE,
  CONSTRAINT `performance_record_splits_professional_id_foreign` FOREIGN KEY (`professional_id`) REFERENCES `professionals` (`id`) ON DELETE SET NULL
