INSERT INTO `sections` VALUES (1,NULL,'App\\Models\\Page',1,'hero','Remedic, il centro medico pensato su di te','Centro polispecialistico ad Acireale','Visite, diagnostica e percorsi di prevenzione coordinati in uno spazio medico pensato per essere piu chiaro, accessibile e umano.','{\"side_note_title\":\"Un unico riferimento\",\"ctas\":[{\"label\":\"Prenota una visita\",\"href\":\"/contatti\"},{\"label\":\"Contattaci\",\"href\":\"/contatti\",\"variant\":\"outline\"}]}',0,1,'2026-06-14 11:01:13','2026-06-14 11:01:13'),(2,NULL,'App\\Models\\Page',1,'approach_items','Il nostro approccio','Un centro medico che prova a rendere piu semplice il rapporto tra persone, specialisti e prevenzione',NULL,'{\"items\":[{\"title\":\"Persona al centro\",\"text\":\"Ogni percorso nasce dall’ascolto e dall’esigenza concreta della persona, non da una proposta standard.\"},{\"title\":\"Ascolto e personalizzazione\",\"text\":\"Orientiamo visite, diagnostica e controlli in modo chiaro, costruendo un’esperienza piu semplice e comprensibile.\"},{\"title\":\"Professionalita e coordinamento\",\"text\":\"Mettiamo in relazione specialisti e prestazioni per evitare frammentazioni e rendere piu lineare il percorso di cura.\"},{\"title\":\"Prevenzione e continuita\",\"text\":\"Crediamo in una medicina che accompagna nel tempo, con controlli utili, follow-up e prevenzione consapevole.\"}]}',1,1,'2026-06-14 11:01:13','2026-06-14 11:01:13'),(3,NULL,'App\\Models\\Page',1,'what_you_find_items','Cosa trovi in Remedic','Aree mediche, percorsi e servizi costruiti per rendere piu lineare il tuo accesso alla salute',NULL,'{\"items\":[{\"title\":\"Visite specialistiche\",\"text\":\"Aree mediche coordinate per affrontare sintomi, controlli e follow-up.\"},{\"title\":\"Diagnostica\",\"text\":\"Esami e approfondimenti utili per rendere piu rapido il percorso di valutazione.\"},{\"title\":\"Check-up\",\"text\":\"Percorsi di prevenzione pensati per eta, fattori di rischio e obiettivi di salute.\"},{\"title\":\"Medicina estetica\",\"text\":\"Consulenze e trattamenti con un approccio medico, responsabile e personalizzato.\"},{\"title\":\"Medicina di genere\",\"text\":\"Percorsi costruiti sulle esigenze di donne e uomini nelle diverse fasi della vita.\"},{\"title\":\"Percorsi personalizzati\",\"text\":\"Orientamento e combinazioni di visite o controlli pensati sulle esigenze reali della persona.\"}]}',2,1,'2026-06-14 11:01:13','2026-06-14 11:01:13'),(4,NULL,'App\\Models\\Page',1,'why_remedic_items','Perche scegliere Remedic','Un centro pensato per offrire piu continuita tra visite, prevenzione e orientamento',NULL,'{\"items\":[\"Centro polispecialistico ad Acireale.\",\"Piu specialita in un unico luogo, con un accesso piu semplice.\",\"Prenotazione e orientamento con un linguaggio chiaro.\",\"Attenzione concreta alla persona e ai suoi tempi.\",\"Percorsi coordinati tra visite, diagnostica e prevenzione.\"],\"note_title\":\"Il centro\",\"note_text\":\"Ambulatori, spazi di consulto e un ambiente clinico ordinato per accoglierti con un’esperienza piu chiara e rassicurante.\"}',3,1,'2026-06-14 11:01:13','2026-06-14 11:01:13'),(5,NULL,'App\\Models\\Page',1,'team_intro','L’equipe Remedic','Un gruppo di specialisti con competenze diverse, pensato per offrire orientamento e continuita di cura.',NULL,'[]',4,1,'2026-06-14 11:01:13','2026-06-14 11:01:13'),(6,NULL,'App\\Models\\Page',1,'cta','Hai bisogno di una visita o di un percorso personalizzato?',NULL,'Il team Remedic ti aiuta a trovare la visita, il controllo o il percorso piu adatto alle tue esigenze.','[]',5,1,'2026-06-14 11:01:13','2026-06-14 11:01:13'),(7,NULL,'App\\Models\\Page',2,'hero','Privacy Policy','Informativa dati personali','Informazioni sul trattamento dei dati personali raccolti tramite il sito e i canali di contatto Remedic.','{\"side_note_title\":\"Pagina in revisione\",\"side_note_text\":\"La struttura e pronta per ospitare il testo legale definitivo. I contenuti vanno verificati e completati con il consulente privacy.\",\"meta_items\":[{\"label\":\"Ambito\",\"value\":\"Sito e contatti Remedic\"},{\"label\":\"Aggiornamento\",\"value\":\"Da verificare\"},{\"label\":\"Supporto\",\"value\":\"Contatti privacy dedicati\"}]}',0,1,'2026-06-14 11:01:13','2026-06-14 11:01:13'),(8,NULL,'App\\Models\\Page',2,'titolare','Titolare del trattamento',NULL,NULL,'{\"items\":[\"Il presente testo deve essere verificato e completato con i riferimenti definitivi del titolare del trattamento dei dati personali e con gli eventuali recapiti privacy dedicati.\",\"Remedic utilizza questa pagina per fornire informazioni sul trattamento dei dati raccolti tramite navigazione, richieste informative, prenotazioni e utilizzo dei servizi presenti sul sito.\"]}',1,1,'2026-06-14 11:01:13','2026-06-14 11:01:13'),(9,NULL,'App\\Models\\Page',2,'dati-trattati','Tipologie di dati trattati',NULL,NULL,'{\"items\":[\"Possono essere trattati dati identificativi e di contatto inseriti volontariamente dall’utente, oltre a dati tecnici legati alla navigazione e all’utilizzo dei servizi digitali del sito.\",\"Eventuali dati relativi a richieste di prenotazione o orientamento sanitario devono essere trattati secondo procedure e informative specifiche da validare con il consulente privacy.\"]}',2,1,'2026-06-14 11:01:13','2026-06-14 11:01:13'),(10,NULL,'App\\Models\\Page',2,'finalita','Finalita del trattamento',NULL,NULL,'{\"items\":[\"I dati possono essere trattati per rispondere a richieste informative, gestire contatti e prenotazioni, migliorare l’esperienza di navigazione e garantire il corretto funzionamento dei servizi digitali.\",\"Ulteriori finalita, basi giuridiche e tempi di conservazione devono essere confermati nella versione legale definitiva della policy.\"]}',3,1,'2026-06-14 11:01:13','2026-06-14 11:01:13'),(11,NULL,'App\\Models\\Page',2,'base-giuridica','Base giuridica',NULL,NULL,'{\"items\":[\"La base giuridica del trattamento deve essere definita in relazione alle specifiche attivita svolte: esecuzione di misure precontrattuali, adempimenti normativi, legittimo interesse o consenso quando richiesto.\",\"Questa sezione e predisposta per una revisione formale con il professionista che segue la conformita privacy del progetto.\"]}',4,1,'2026-06-14 11:01:13','2026-06-14 11:01:13'),(12,NULL,'App\\Models\\Page',2,'modalita','Modalita del trattamento',NULL,NULL,'{\"items\":[\"I dati possono essere trattati con strumenti digitali e organizzativi idonei a garantire sicurezza, riservatezza e controllo degli accessi, nel rispetto della normativa applicabile.\",\"Le misure tecniche e organizzative specifiche devono essere confermate nel documento definitivo.\"]}',5,1,'2026-06-14 11:01:13','2026-06-14 11:01:13'),(13,NULL,'App\\Models\\Page',2,'conservazione','Conservazione dei dati',NULL,NULL,'{\"items\":[\"I tempi di conservazione devono essere determinati in base alla finalita del trattamento, agli obblighi di legge e alle procedure interne applicabili ai servizi offerti.\",\"In questa fase la sezione resta come struttura da completare con indicazioni puntuali e validate.\"]}',6,1,'2026-06-14 11:01:13','2026-06-14 11:01:13'),(14,NULL,'App\\Models\\Page',2,'diritti','Diritti dell’interessato',NULL,NULL,'{\"items\":[\"Gli utenti possono esercitare i diritti previsti dalla normativa applicabile, tra cui accesso, rettifica, cancellazione, limitazione, opposizione e, ove previsto, portabilita dei dati.\",\"Le modalita operative per l’esercizio di tali diritti devono essere esplicitate nella versione finale della policy.\"]}',7,1,'2026-06-14 11:01:13','2026-06-14 11:01:13'),(15,NULL,'App\\Models\\Page',2,'contatti-privacy','Contatti privacy',NULL,NULL,'{\"items\":[\"I recapiti privacy dedicati devono essere confermati e inseriti in modo definitivo prima della pubblicazione finale della policy.\",\"Fino a quel momento, questa pagina funge da struttura leggibile e coerente con il sito, pronta per la revisione legale conclusiva.\"]}',8,1,'2026-06-14 11:01:13','2026-06-14 11:01:13'),(16,NULL,'App\\Models\\Page',3,'hero','Cookie Policy','Informativa cookie','Informazioni sull’utilizzo dei cookie e sulle preferenze di consenso del sito Remedic.','{\"side_note_title\":\"Preferenze cookie\",\"side_note_text\":\"Il sito e predisposto per gestire le preferenze di consenso. La policy finale va completata con il dettaglio tecnico dei cookie effettivamente utilizzati.\",\"meta_items\":[{\"label\":\"Ambito\",\"value\":\"Navigazione e preferenze\"},{\"label\":\"Consenso\",\"value\":\"Gestibile dal pannello cookie\"},{\"label\":\"Verifica\",\"value\":\"Da completare\"}]}',0,1,'2026-06-14 11:01:13','2026-06-14 11:01:13'),(17,NULL,'App\\Models\\Page',3,'cosa-sono','Cosa sono i cookie',NULL,NULL,'{\"items\":[\"I cookie sono piccoli file di testo che permettono al sito di funzionare correttamente, ricordare preferenze o raccogliere informazioni tecniche e statistiche sulla navigazione.\",\"La classificazione puntuale dei cookie utilizzati deve essere confermata nella versione legale definitiva della policy.\"]}',1,1,'2026-06-14 11:01:13','2026-06-14 11:01:13'),(18,NULL,'App\\Models\\Page',3,'cookie-tecnici','Cookie tecnici',NULL,NULL,'{\"items\":[\"I cookie tecnici supportano funzioni essenziali del sito, come la navigazione, la sicurezza e la corretta erogazione dei contenuti richiesti dall’utente.\",\"Questa sezione va integrata con l’elenco effettivo dei cookie tecnici presenti nel progetto e con le relative durate.\"]}',2,1,'2026-06-14 11:01:13','2026-06-14 11:01:13'),(19,NULL,'App\\Models\\Page',3,'cookie-analitici','Cookie analitici',NULL,NULL,'{\"items\":[\"Eventuali cookie analitici permettono di comprendere come viene utilizzato il sito e aiutano a migliorare struttura, contenuti e percorsi informativi.\",\"La policy definitiva dovra specificare se tali strumenti sono configurati in forma aggregata, anonimizzata o soggetti a consenso.\"]}',3,1,'2026-06-14 11:01:13','2026-06-14 11:01:13'),(20,NULL,'App\\Models\\Page',3,'terze-parti','Cookie di terze parti',NULL,NULL,'{\"items\":[\"Componenti esterni o integrazioni di terze parti possono comportare l’utilizzo di cookie o tecnologie analoghe soggette alle rispettive informative.\",\"I fornitori effettivamente coinvolti e i relativi link informativi vanno verificati e inseriti nella revisione conclusiva.\"]}',4,1,'2026-06-14 11:01:13','2026-06-14 11:01:13'),(21,NULL,'App\\Models\\Page',3,'preferenze','Gestione preferenze',NULL,NULL,'{\"items\":[\"Le preferenze di consenso possono essere gestite tramite il sistema cookie del sito quando attivo, distinguendo tra strumenti necessari e categorie opzionali.\",\"Questa pagina e predisposta per collegarsi al pannello reale di gestione del consenso gia presente nel progetto.\"]}',5,1,'2026-06-14 11:01:13','2026-06-14 11:01:13'),(22,NULL,'App\\Models\\Page',3,'aggiornamenti','Aggiornamenti della policy',NULL,NULL,'{\"items\":[\"La cookie policy puo essere aggiornata nel tempo per adeguarsi a modifiche tecniche, normative o organizzative relative al sito e ai servizi connessi.\",\"La data di ultimo aggiornamento deve essere definita nella versione finale del testo approvato.\"]}',6,1,'2026-06-14 11:01:13','2026-06-14 11:01:13'),(23,NULL,'App\\Models\\Page',3,'preferences_cta','Modifica le tue preferenze cookie',NULL,'Se il sistema di consenso e attivo, puoi riaprire il pannello dedicato e aggiornare in qualsiasi momento le tue preferenze.','[]',7,1,'2026-06-14 11:01:13','2026-06-14 11:01:13');
/*!40000 ALTER TABLE `sections` ENABLE KEYS */;
