--
-- Table structure for table `services`
--

DROP TABLE IF EXISTS `services`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `services` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `legacy_backend_id` bigint(20) unsigned DEFAULT NULL,
  `category_id` bigint(20) unsigned DEFAULT NULL,
  `canonical_name` varchar(255) NOT NULL,
  `display_name` varchar(255) NOT NULL,
  `importo_prestazione` decimal(10,2) DEFAULT NULL,
  `slug` varchar(255) NOT NULL,
  `description` text DEFAULT NULL,
  `short_description` text DEFAULT NULL,
  `intro_text` text DEFAULT NULL,
  `local_intro_text` text DEFAULT NULL,
  `local_area_notes` text DEFAULT NULL,
  `preparation_notes` text DEFAULT NULL,
  `duration_text` varchar(255) DEFAULT NULL,
  `price_text` varchar(255) DEFAULT NULL,
  `exam_report_time` varchar(255) DEFAULT NULL,
  `featured_image_path` varchar(255) DEFAULT NULL,
  `social_image_path` varchar(255) DEFAULT NULL,
  `is_diagnostic` tinyint(1) NOT NULL DEFAULT 0,
  `is_visit` tinyint(1) NOT NULL DEFAULT 0,
  `is_featured` tinyint(1) NOT NULL DEFAULT 0,
  `is_local_seo_enabled` tinyint(1) NOT NULL DEFAULT 1,
  `seo_title` varchar(255) DEFAULT NULL,
  `local_seo_title` varchar(255) DEFAULT NULL,
  `seo_description` text DEFAULT NULL,
  `local_seo_description` text DEFAULT NULL,
  `seo_h1` varchar(255) DEFAULT NULL,
  `local_seo_h1` varchar(255) DEFAULT NULL,
  `canonical_url` varchar(255) DEFAULT NULL,
  `robots` varchar(255) NOT NULL DEFAULT 'index,follow',
  `og_title` varchar(255) DEFAULT NULL,
  `og_description` text DEFAULT NULL,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `default_duration_minutes` smallint(5) unsigned DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `is_web_active` tinyint(1) NOT NULL DEFAULT 1,
  `notes` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `services_slug_unique` (`slug`),
  UNIQUE KEY `services_legacy_backend_id_unique` (`legacy_backend_id`),
  KEY `services_category_id_foreign` (`category_id`),
  KEY `services_is_active_index` (`is_active`),
  KEY `services_is_diagnostic_index` (`is_diagnostic`),
  KEY `services_is_visit_index` (`is_visit`),
  KEY `services_is_featured_index` (`is_featured`),
  KEY `services_sort_order_index` (`sort_order`),
  CONSTRAINT `services_category_id_foreign` FOREIGN KEY (`category_id`) REFERENCES `service_categories` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=569 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

